  'gloss.ceramah': 'A political talk, usually at night, where a leader speaks to a crowd. The classic way to campaign, strongest in the kampung.',
  'gloss.machinery': 'Your party’s branches and volunteers on the ground. They find supporters, and in the final weeks get them to the polls. They take time to build.',
  'gloss.hung': 'An election in which no party wins a majority of the seats, so the parties must bargain to form a government.',
  'gloss.moe': 'How far a poll can be off by chance alone. A lead smaller than the margin is not a real lead.',
  'gloss.unity': 'How well your party holds together. Deals and concessions spend it, and if it falls too low the party removes its leader.',
  'gloss.credibility': 'How far voters believe your positions and promises. Policy work builds it slowly.',
  'gloss.safe': 'A seat won by 15 points or more. It rarely changes hands in one campaign.',
  'gloss.leaning': 'A seat won by between 5 and 15 points. It can be taken, with work.',
  'gloss.marginal': 'A seat won by fewer than 5 points. These decide elections, and are where a day of campaigning counts most.',
  'gloss.orders': 'What your party does week after week between elections without being asked again: where the money goes and what you spend your own time on.',
  'gloss.dossier': 'What your researchers have dug up on your rivals. It makes your attacks hit harder and backfire less, and each attack uses some of it up.',
  'gloss.stability': 'How firmly the government holds together. Below 50 it is shaky; below 30 it is on the brink, and partners start to walk.',
  'gloss.trust': 'How far the public believes the government is honest. Leaning on institutions and shady deals spend it.',
