  'platform.how': 'How does your party begin?',
  'platform.takeover': 'Take over a big party',
  'platform.takeover.desc': 'Start with the seats, money and machinery of the party you picked above, under your own name.',
  'platform.new': 'Found a new party from nothing',
  'platform.new.desc.single': 'A party with no past and no machinery: a name of your own, a small purse and a following of a few per cent of the vote in every seat. An uphill fight, and a good one to win.',
  'platform.new.desc': 'One seat and about half a per cent of the vote, a small purse and a platform that is all yours. You grow it term by term, among the voters whose wishes it matches.',
  'platform.title': 'Your platform',
  'platform.note': 'Where you stand decides where you grow: each group of voters comes to you in proportion to how closely your platform matches what it wants. You can change it later in the Policy tab, at a price in credibility.',
  'platform.presets': 'Starting points',
  'platform.blank': 'Centre ground',
  'platform.founded.name': 'New Party',
  'platform.founded.short': 'NEW',
  'platform.founded.leader': 'The Founder',
  'action.townhall': 'Open town hall',
  'action.townhall.desc': 'Questions from the floor in one seat. Wins over towns and suburbs, little in the villages, and one time in five you say something you regret.',
  'action.charity': 'Community aid drive',
  'action.charity.desc': 'Help for a state’s poorest households and villages, with a turnout lift. Costly, and one time in six it is reported as buying votes (more if you are over the spending limit).',
  'action.youth': 'Youth drive',
  'action.youth.desc': 'Campuses and gig hubs in a state. Wins first-time voters and gig workers, and brings young voters to the polls, which helps whoever else they like too.',
  'action.festival': 'People’s carnival',
  'action.festival.desc': 'A little goodwill from everyone in a state, every time, and the party feels like a movement: unity up. Wins no one outright.',
  'action.conference': 'Party conference',
  'action.conference.desc': 'A day spent on the party, not the voters: unity up sharply and branches nearby take heart. Gains no votes.',
  'action.debate': 'Challenge to a TV debate',
  'action.debate.desc': 'Win and you gain with the voters who watch, and your rival loses ground. Lose and you pay for it. The better speaker usually wins, and a repeat is worth less.',
  'action.manifesto': 'Launch the manifesto',
  'action.manifesto.desc': 'Once a campaign. Wins graduates, professionals and the suburbs. A divided party launches it badly, and a believed leader sells it better.',
  'action.local': 'Local event',
  'action.local.desc': 'The thing that is done in this state and in no other: a custom, a harvest, a festival. It lands on the groups that belong to the place, and the party’s own people are proud of it.',
  'news.me.local': 'The party takes part in the local custom in {state}. The people of the place remember who came.',
  'media.aim.title': 'Aim at one group',
  'media.aim.note': 'Television, radio and social media can be aimed at one group of voters. They hear it better; the groups unlike them hear less, and those set against it may turn away.',
  'local.nsembilan': 'Adat perpatih gathering',
  'local.sabah': 'Kaamatan harvest festival',
  'local.sarawak': 'Gawai Dayak',
  'local.kelantan': 'Majlis ilmu and the mosque feast',
  'local.terengganu': 'Majlis ilmu and the coast festival',
  'local.kedah': 'Padi harvest feast',
  'local.perlis': 'Kampung kenduri',
  'local.pahang': 'FELDA settlers’ day',
  'local.penang': 'Street-food festival',
  'local.selangor': 'Technology and gig-work fair',
  'local.perak': 'Ipoh heritage week',
  'local.melaka': 'Heritage week',
  'local.johor': 'Great kenduri',
  'local.kl': 'City night market',
  'local.putrajaya': 'Civil servants’ open day',
  'local.labuan': 'Harbour festival',
  'action.radio': 'Local radio slot',
  'action.radio.desc': 'Cheap airtime across a state. Reaches villages, pensioners and the interior; barely touches the cities.',
  'news.me.townhall.ok': 'Town hall in {seat}: sharp questions, and you had answers.',
  'news.me.townhall.flop': 'Town hall in {seat}: one answer too many, and the clip is everywhere.',
  'news.me.charity.ok': 'Aid drive in {state}: queues of grateful families.',
  'news.me.charity.backfire': 'Aid drive in {state}: the papers call it vote-buying, and the Commission takes note.',
  'news.me.youth': 'Youth drive in {state}: packed halls, and a long line of first-time voters.',
  'news.me.festival': 'Carnival in {state}: the party’s own people left with their heads high.',
  'news.me.conference': 'Party conference: old quarrels aired and settled, and the branches go home united.',
  'news.me.debate.won': 'You won the debate against {party}. The clips run all week.',
  'news.me.debate.lost': 'You lost the debate against {party}. Your own side will not mention it.',
  'news.me.manifesto.ok': 'Your manifesto is out and the commentators are reading it.',
  'news.me.manifesto.weak': 'Your manifesto is out, but a divided party launched it, and nobody believes the unity on stage.',
  'news.me.radio': 'Radio slots across {state}: your voice in every kitchen.',
  'vacancy.choose': 'Choose a seat',
  'vacancy.random': 'Random close race',
  'vacancy.search': 'Search by name, code or state',
  'vacancy.count': '{n} seats',
  'vacancy.none': 'No seat matches.',
  'vacancy.parliament': 'Parliamentary seats',
  'vacancy.dun': 'State assembly seats',
  'vacancy.close': 'Close race',
  'adviser.home.welcome': 'Boss, welcome home. The seat is vacant and we have three weeks to take it. This is our ground: the branches are ours, and we start with a fuller war chest than the parties from across the sea bring with them. I will walk you through it.',
  'adviser.home.welcomeHeld': 'Boss, welcome home. The seat is vacant and we have three weeks to hold it. We won it last time, and this is our ground: the branches are ours, and we start with a fuller war chest than the parties from across the sea bring with them. I will walk you through it.',
  'adviser.home.funds': 'We started with more than the visitors, but it runs out all the same. Raise some: a fundraising dinner or an online appeal.',
  'adviser.home.rivals': 'The national parties did not sit still. The News tab shows what they did in public. They come with bigger names; we have the branches and we were here first. And remember: what we did last week is already fading.',
  'adviser.home.middle': 'Keep going. The same thing in the same place gives less each time, so mix it up: ceramah, walkabouts, the machinery, a little online. Do not let them make this about the country; keep it about here.',
  'quick.home': 'Or lead a party of Sabah or Sarawak on its own ground:',
  'adviser.welcomeAny': 'Boss, welcome. The seat has fallen vacant and we have three weeks to take it. I will walk you through it.',
  'adviser.welcomeAnyHeld': 'Boss, welcome. The seat has fallen vacant and we have three weeks to hold it. We won it last time. I will walk you through it.',
  'nation.title': 'State of the nation',
  'nation.health': 'Health',
  'nation.education': 'Education',
  'nation.standing': 'Standing abroad',
  'nation.weak': 'Weak',
  'nation.fair': 'Fair',
  'nation.strong': 'Strong',
  'nation.note.gov': 'These are yours to answer for. They move slowly with the budget’s health and education lines, the ministers, and how steady and believed the government is, and they jump when something happens. Voters notice.',
  'nation.note.opp': 'The government answers for these. They move slowly with its budget, its ministers and its steadiness, and jump when something happens. Voters notice, and so can you.',
