  'title.intro': 'Lead a party to polling day. Start with a single seat, fight for a state, or take on all 222 seats.',
  'title.contest': 'Contest',
  'title.startHere': 'Start here',
  'quick.title': 'Quick start',
  'quick.body': 'A three-week by-election, with {adviser} beside you explaining each step. No setup needed.',
  'quick.party': 'You lead',
  'quick.start': 'Start the tutorial',
  'quick.customise': 'Customise instead',
  'quick.later': 'Other contests, a leader with a backstory, a party of your own and the difficulty are under Customise.',
  'quick.back': 'Back to quick start',
  'title.fiction': 'A satire. Every party and person in it is invented.',
  'credits.title': 'About and credits',
  'credits.fiction': 'Kempen 222 is a work of fiction and satire. Every party, leader, minister, candidate, news outlet, event and news story in it is invented. Any resemblance to a real person or organisation is a feature of the parody, not a statement of fact about anyone. It is not affiliated with or endorsed by any political party, government body, the Palace, or any institution it mentions.',
  'credits.data': 'The map, seat list, voter numbers and past results are real public data, changed for the game as described below.',
  'credits.dosm': 'Department of Statistics Malaysia (DOSM): seat and state boundaries and 2020 census figures, under its Open Data Licence. This is not an official DOSM product and DOSM does not endorse it.',
  'credits.tindak': 'Tindak Malaysia: the GE15 results dataset, under',
  'credits.link.dosm': 'DOSM open data',
  'credits.link.tindak': 'GE15 dataset',
  'credits.tindak2': 'Tindak Malaysia: results of the state elections of Melaka and Sarawak (2021), five states in August 2023, Sabah (2025), and Johor and Negeri Sembilan (2026). Its sources: the Election Commission of Malaysia, Tindak Malaysia, the Attorney General’s Chambers, Bernama, RTM, Berita Harian, Sinar Harian, Harian Metro, Kosmo, Utusan Malaysia, Malaysiakini, Free Malaysia Today, Malaysia Gazette, Harakahdaily, The Edge, New Straits Times, The Star, Utusan TV, Astro Awani, Akhbar Rakyat, Sinar Project, and the parties’ own pages and publications (listed in full in the project’s data notes). Under',
  'credits.link.tindak2': 'historical election results',
  'credits.changes': 'Changes made: real coalitions are replaced by fictional parties; small parties and independents are pooled; boundaries are simplified; and each seat’s mix of voter blocs is an estimate from census figures, not a published statistic. In the six states that voted in 2023, and in Sabah, two allied parties stood aside for each other in every seat; what each would poll with everyone standing is an estimate too. In Sabah, the parties that later governed together stood under two banners, which are counted as one party.',
  'error.title': 'Something went wrong',
  'error.body': 'The game hit an unexpected error. It saves automatically on this device, so reloading should bring you back. If you want to be safe, export the current game to a file first.',
  'error.reload': 'Reload the game',
  'error.export': 'Export my game',
