  'adviser.danger.credibility': 'Credibility is down to {n}. Voters stop believing a party that keeps changing its mind. Hold your stances for a while.',
  'adviser.danger.stability': 'Stability is down to {n}. A government this shaky can fall to a single vote. Look at the Orders tab.',
  'adviser.danger.trust': 'Public trust is down to {n}. The next election will be hard unless it recovers. Look at the Orders tab.',
  'adviser.danger.go': 'Take me there',
  'adviser.danger.later': 'Not this week',
  'adviser.show': 'Show me',
  'adviser.welcome': 'Boss, welcome. The MP has stepped down and we have three weeks to take the seat. Last time it was a close three-way fight and we came up short. I will walk you through it.',
  'adviser.welcomeHeld': 'Boss, welcome. The MP has stepped down and we have three weeks to hold the seat. We won it last time, in a close three-way fight. I will walk you through it.',
  'adviser.seat': 'First, look at the ground. Click the seat on the map to open its file.',
  'adviser.ceramah': 'Good. Now try a ceramah: in the Actions tab, hold one. It costs a day and some money. How well it works depends on the seat, and rural seats take to ceramah most.',
  'adviser.poll': 'Did it help? We cannot know without asking. Open the Polls tab and commission a seat poll. Quick is cheap and rough; Full costs more and is sharper.',
  'adviser.canvass': 'Every poll has a margin of error, so do not celebrate small moves. Now put the machinery to work: run a door-to-door drive from the Actions tab.',
  'adviser.funds': 'All of this costs money, and we do not have much. Raise some: a fundraising dinner or an online appeal.',
  'adviser.endWeek': 'There are only seven days in a week. When you have used what you want, press End week. Unused days are gone for good.',
  'adviser.rivals': 'The others did not sit still. The News tab shows what they did in public. And remember: what we did last week is already fading, so the final week counts most.',
  'adviser.middle': 'Keep going. The same thing in the same place gives less each time, so mix it up: ceramah, walkabouts, the machinery, a little social media. End the week when you are done.',
  'adviser.gotv': 'Final week. Persuading is nearly over; now we get our own people to the polling station. Run Get out the vote from the Actions tab.',
  'adviser.pollingDay': 'That is all we can do. Spend your remaining days, then press Go to the polls. Whatever happens, you ran a proper campaign.',

  'tab.chiefs': 'Chiefs',
  'chiefs.title.general': 'State chiefs',
  'chiefs.title.state': 'Division chiefs',
  'chiefs.count': '{n} of {total} in charge',
  'chiefs.intro.general': 'Put a state chief in charge and they run the ground campaign in that state for you: ceramah and walkabouts in the closest seats, door-to-door drives, billboards, new branches and getting out the vote. It takes none of your days. They spend the party’s money, and their events draw half the crowd yours would.',
  'chiefs.intro.state': 'Put a division chief in charge and they run the ground campaign in that area for you: ceramah and walkabouts in the closest seats, door-to-door drives, billboards, new branches and getting out the vote. It takes none of your days. They spend the party’s money, and their events draw half the crowd yours would.',
  'chiefs.when': 'Chiefs act when you end the week. They hold back early, spend most in the final weeks, and skip whatever you have already done yourself.',
  'chiefs.people': 'A chief is a person. An able one draws a bigger crowd. Each stays loyal while you turn up in their region and cools while you stay away; one left to cool may cross to a rival and take branches with them.',
  'chiefs.skill': 'Ability',
  'chiefs.mood.loyal': 'Loyal',
  'chiefs.mood.cooling': 'Cooling',
  'chiefs.mood.restless': 'Restless',
  'news.chief.restless': '{name}, your chief in {state}, is telling people you have forgotten the place.',
  'news.chief.defected': '{name}, your chief in {state}, has crossed to {party} and taken branches along. A deputy is waiting to be appointed.',
  'news.chief.exposed': 'An old story about {name}, your chief in {state}, is on every front page. They have stepped down, and a deputy is waiting to be appointed.',
  'chiefs.all': 'Set all',
  'chiefs.floor': 'Chiefs must leave at least',
  'chiefs.floor.none': 'Nothing',
  'chiefs.none': 'No chief is in charge anywhere: you run every campaign yourself.',
  'chiefs.allowance': 'This week your chiefs may spend up to {rm} between them.',
  'chiefs.levels': 'Lean is one operation a week, Standard two, All out up to four.',
