  'voice.ps.accept': 'For the sake of reform, we can work together. Mostly.',
  'voice.ps.refuse': 'My people would never forgive me. Not at this price.',
  'voice.bp.accept': 'Stability comes first. We have always said so, since this morning.',
  'voice.bp.refuse': 'We were in government for sixty years. We know what a serious offer looks like.',
  'voice.pt.accept': 'A government of principle. We will hold you to every line.',
  'voice.pt.refuse': 'We do not trade our principles. Not for so little.',
  'voice.gbk.accept': 'We back whoever respects the agreement. Today, that is you.',
  'voice.gbk.refuse': 'We are in no hurry. The longer you wait, the more we are worth.',
  'voice.gbs.accept': 'Sabah’s interests are protected. So, I am told, are mine.',
  'voice.gbs.refuse': 'Come back when the offer has more zeroes, or more ministries.',
  'voice.legasi.accept': 'We will stand with you. Do not forget who stood with you.',
  'voice.legasi.refuse': 'We have been promised things before.',
  'voice.oth.accept': 'The independents discover that they have always admired you.',
  'voice.oth.refuse': 'The independents remain independent, for now.',
  'voice.genba.accept': 'We were sent to Parliament to change things. This is a start.',
  'voice.genba.refuse': 'Our voters did not queue for hours to watch us sign this.',
  'voice.cahaya.accept': 'Sarawak’s voice will be heard. We will make sure of it.',
  'voice.cahaya.refuse': 'Our door is open. This offer has not yet reached it.',
  'voice.suara.accept': 'The interior has waited long enough. We will sign.',
  'voice.suara.refuse': 'Roads, clinics, then signatures. In that order.',

