  'party.title': 'The party',
  'party.none': 'This contest has no party organisation to run: it is a single campaign.',
  'party.intro': 'Between elections the party is an organisation: members who pay their dues and knock on doors, businesses that earn and sometimes lose, and things it does before a campaign is called. Branches, unity and standing keep the rolls where they are.',
  'party.members': 'Members',
  'party.trend': 'Rolls',
  'party.trend.growing': 'growing',
  'party.trend.shrinking': 'shrinking',
  'party.trend.steady': 'steady',
  'party.branches': 'Branch strength',
  'party.members.note': 'A party of this size ordinarily has about {ordinary} members. More members mean more in dues each week.',
  'party.activities': 'What the party does',
  'party.activities.desc': 'Each costs money and cannot be repeated for a while.',
  'party.activities.campaign': 'These are done in the years between elections, not in a campaign.',
  'activity.recruit': 'Membership drive',
  'activity.recruit.desc': 'A table at every market and mosque for a month. The rolls jump, and stay higher for a while.',
  'activity.assembly': 'Annual general assembly',
  'activity.assembly.desc': 'Speeches, resolutions and a dinner at which everyone is reconciled. Mends a divided party.',
  'activity.school': 'School for cadres',
  'activity.school.desc': 'Branch officers learn to keep a register and count a vote. Every branch the party has is a little stronger.',
  'activity.every': 'once in {n} weeks',
  'activity.wait': 'Again in {n} weeks.',
  'party.holdings': 'What the party owns',
  'party.holdings.desc': 'Each is bought and sold in lots. Each pays in its own way, and each can go wrong in its own way.',
  'party.holding.value': 'Held {value} · {rm} a week',
  'party.holding.effect': 'effect {n}%',
  'holding.property': 'Shop lots and land',
  'holding.property.desc': 'The quiet money. Pays steadily and rarely goes wrong.',
  'holding.hotel': 'A hotel',
  'holding.hotel.desc': 'Pays better than land, and is where deals get done. And where the cameras sometimes are.',
  'holding.media': 'A newspaper and a website',
  'holding.media.desc': 'Little money in it, but it keeps the party in the public eye. A libel suit now and then.',
  'holding.plantation': 'A plantation',
  'holding.plantation.desc': 'Palm oil and rubber in the countryside the party depends on. The price goes where it likes.',
  'holding.college': 'A training college',
  'holding.college.desc': 'Loses money every week. Grows the membership and keeps the party together.',
  'news.holding.property': 'A tenant defaults and a block of shops stands empty: part of the party’s property income goes with it.',
  'news.holding.hotel': 'A party hotel is in the papers: who was seen in which room, and who paid. The party’s name suffers, and so does the hotel’s trade.',
  'news.holding.media': 'The party’s paper is sued for libel and loses. The settlement comes out of the party’s pocket.',
  'news.holding.plantation': 'The price of palm oil collapses, and the party’s plantation loses a good part of its value.',
  'news.holding.college': 'The college is found to have been running at a loss no one had noticed.',
  'news.activity.recruit': 'The membership drive ends with the rolls at {n}.',
  'news.activity.assembly': 'The assembly passes every resolution and the party leaves it together, for now.',
  'news.activity.school': 'A new class of cadres goes back to its branches.',
