  'gloss.ceramah': 'Ucapan politik, biasanya pada waktu malam, di hadapan orang ramai. Cara berkempen yang paling klasik, paling kuat di kampung.',
  'gloss.machinery': 'Cawangan dan sukarelawan parti di lapangan. Mereka mencari penyokong, dan pada minggu akhir membawa mereka mengundi. Ia ambil masa untuk dibina.',
  'gloss.hung': 'Pilihan raya yang tiada parti menang majoriti kerusi, jadi parti-parti perlu berunding untuk membentuk kerajaan.',
  'gloss.moe': 'Sejauh mana tinjauan boleh tersasar secara kebetulan sahaja. Pendahuluan yang lebih kecil daripada ralat bukan pendahuluan sebenar.',
  'gloss.unity': 'Betapa kukuhnya parti anda bersatu. Perjanjian dan konsesi menghabiskannya, dan jika terlalu rendah parti akan menyingkirkan pemimpinnya.',
  'gloss.credibility': 'Setakat mana pengundi percaya pendirian dan janji anda. Kerja dasar membinanya perlahan-lahan.',
  'gloss.safe': 'Kerusi yang dimenangi dengan 15 mata atau lebih. Jarang bertukar tangan dalam satu kempen.',
  'gloss.leaning': 'Kerusi yang dimenangi dengan antara 5 dan 15 mata. Boleh dirampas, dengan usaha.',
  'gloss.marginal': 'Kerusi yang dimenangi dengan kurang daripada 5 mata. Kerusi inilah yang menentukan pilihan raya, dan di sinilah sehari berkempen paling bernilai.',
  'gloss.orders': 'Apa yang parti anda lakukan minggu demi minggu antara pilihan raya tanpa perlu diarah semula: ke mana wang pergi dan apa yang anda sendiri tumpukan.',
  'gloss.dossier': 'Apa yang penyelidik anda korek tentang pesaing. Ia menjadikan serangan anda lebih berbisa dan kurang memakan diri, dan setiap serangan menggunakan sebahagiannya.',
  'gloss.stability': 'Betapa kukuhnya kerajaan bertahan. Bawah 50 ia goyah; bawah 30 ia di ambang jatuh, dan rakan gabungan mula beredar.',
  'gloss.trust': 'Setakat mana rakyat percaya kerajaan jujur. Menekan institusi dan urus niaga meragukan menghabiskannya.',
