  'platform.how': 'Bagaimana parti anda bermula?',
  'platform.takeover': 'Ambil alih parti besar',
  'platform.takeover.desc': 'Mulakan dengan kerusi, wang dan jentera parti yang anda pilih di atas, di bawah nama anda sendiri.',
  'platform.new': 'Tubuh parti baharu dari bawah',
  'platform.new.desc.single': 'Parti tanpa sejarah dan tanpa jentera: nama anda sendiri, dompet kecil dan sokongan beberapa peratus undi di setiap kerusi. Pertarungan yang sukar, dan kemenangan yang membanggakan.',
  'platform.new.desc': 'Satu kerusi dan kira-kira setengah peratus undi, dompet kecil dan platform yang sepenuhnya milik anda. Anda membesarkannya penggal demi penggal, dalam kalangan pengundi yang kehendaknya sepadan.',
  'platform.title': 'Platform anda',
  'platform.note': 'Pendirian anda menentukan di mana anda membesar: setiap kumpulan pengundi datang kepada anda mengikut betapa dekatnya platform anda dengan kehendaknya. Anda boleh mengubahnya kemudian di tab Dasar, dengan kos kredibiliti.',
  'platform.presets': 'Titik permulaan',
  'platform.blank': 'Jalan tengah',
  'platform.founded.name': 'Parti Baharu',
  'platform.founded.short': 'BARU',
  'platform.founded.leader': 'Sang Pengasas',
  'action.townhall': 'Dialog terbuka',
  'action.townhall.desc': 'Soal jawab di satu kerusi. Memenangi pekan dan pinggir bandar, kurang di kampung, dan satu kali daripada lima anda tersasul.',
  'action.charity': 'Program bantuan komuniti',
  'action.charity.desc': 'Bantuan untuk isi rumah dan kampung termiskin di sebuah negeri, dengan dorongan keluar mengundi. Mahal, dan satu kali daripada enam ia dilaporkan sebagai membeli undi (lebih kerap jika perbelanjaan melebihi had).',
  'action.youth': 'Kempen belia',
  'action.youth.desc': 'Kampus dan pusat pekerja gig di sebuah negeri. Menarik pengundi kali pertama dan pekerja gig, dan membawa anak muda keluar mengundi, yang turut membantu sesiapa lagi yang mereka suka.',
  'action.festival': 'Karnival rakyat',
  'action.festival.desc': 'Sedikit muhibah daripada semua orang di sebuah negeri, setiap kali, dan parti terasa seperti gerakan: perpaduan naik. Tidak memenangi sesiapa sepenuhnya.',
  'action.conference': 'Mesyuarat parti',
  'action.conference.desc': 'Sehari untuk parti, bukan pengundi: perpaduan naik mendadak dan cawangan berdekatan bersemangat. Tidak menambah undi.',
  'action.debate': 'Cabaran debat TV',
  'action.debate.desc': 'Menang dan anda untung dengan penonton, pesaing rugi. Kalah dan anda menanggungnya. Penutur yang lebih baik biasanya menang, dan debat berulang kurang nilainya.',
  'action.manifesto': 'Lancar manifesto',
  'action.manifesto.desc': 'Sekali sahaja dalam satu kempen. Memenangi graduan, profesional dan pinggir bandar. Parti yang berpecah melancarkannya dengan buruk, dan pemimpin yang dipercayai menjualnya lebih baik.',
  'action.local': 'Acara tempatan',
  'action.local.desc': 'Perkara yang dibuat di negeri ini dan tidak di tempat lain: adat, tuaian, pesta. Ia sampai kepada kumpulan yang tergolong dalam tempat itu, dan orang parti sendiri berbangga dengannya.',
  'news.me.local': 'Parti menyertai adat tempatan di {state}. Orang setempat ingat siapa yang datang.',
  'media.aim.title': 'Sasarkan satu kumpulan',
  'media.aim.note': 'Televisyen, radio dan media sosial boleh disasarkan kepada satu kumpulan pengundi. Mereka mendengarnya lebih baik; kumpulan yang tidak serupa mendengar kurang, dan yang menentangnya mungkin berpaling.',
  'local.nsembilan': 'Majlis adat perpatih',
  'local.sabah': 'Pesta Kaamatan',
