  'action.radio': 'Slot radio tempatan',
  'action.radio.desc': 'Masa siaran murah di seluruh negeri. Sampai ke kampung, pesara dan pedalaman; hampir tidak menyentuh bandar.',
  'news.me.townhall.ok': 'Dialog terbuka di {seat}: soalan tajam, dan anda ada jawapannya.',
  'news.me.townhall.flop': 'Dialog terbuka di {seat}: satu jawapan terlebih, dan klipnya tersebar di mana-mana.',
  'news.me.charity.ok': 'Program bantuan di {state}: barisan keluarga yang berterima kasih.',
  'news.me.charity.backfire': 'Program bantuan di {state}: akhbar menyebutnya membeli undi, dan Suruhanjaya mencatatnya.',
  'news.me.youth': 'Kempen belia di {state}: dewan penuh sesak, dan barisan panjang pengundi kali pertama.',
  'news.me.festival': 'Karnival di {state}: orang parti sendiri pulang dengan kepala tegak.',
  'news.me.conference': 'Mesyuarat parti: pertelingkahan lama dibangkitkan dan diselesaikan, cawangan pulang bersatu.',
  'news.me.debate.won': 'Anda menang debat menentang {party}. Klipnya diputar sepanjang minggu.',
  'news.me.debate.lost': 'Anda kalah debat menentang {party}. Pihak anda sendiri tidak akan menyebutnya.',
  'news.me.manifesto.ok': 'Manifesto anda sudah keluar dan para penganalisis sedang membacanya.',
  'news.me.manifesto.weak': 'Manifesto anda sudah keluar, tetapi parti yang berpecah melancarkannya, dan tiada siapa percaya perpaduan di pentas.',
  'news.me.radio': 'Slot radio di seluruh {state}: suara anda di setiap dapur.',
