  'vacancy.parliament': 'Kerusi Parlimen',
  'vacancy.dun': 'Kerusi DUN',
  'vacancy.close': 'Sengit',
  'adviser.home.welcome': 'Bos, selamat pulang. Kerusi ini kosong dan kita ada tiga minggu untuk merampasnya. Ini tanah kita: cawangan milik kita, dan tabung perang kita lebih penuh daripada yang dibawa parti-parti dari seberang laut. Saya akan tunjukkan caranya.',
  'adviser.home.welcomeHeld': 'Bos, selamat pulang. Kerusi ini kosong dan kita ada tiga minggu untuk mempertahankannya. Kali lalu kita menang, dan ini tanah kita: cawangan milik kita, dan tabung perang kita lebih penuh daripada yang dibawa parti-parti dari seberang laut. Saya akan tunjukkan caranya.',
  'adviser.home.funds': 'Kita bermula dengan lebih banyak daripada tetamu itu, tetapi wang tetap akan habis. Kutip sedikit: majlis makan malam dana atau rayuan dalam talian.',
  'adviser.home.rivals': 'Parti-parti nasional tidak duduk diam. Tab Berita menunjukkan apa yang mereka buat secara terbuka. Mereka datang dengan nama besar; kita ada cawangan dan kita di sini dahulu. Dan ingat: apa yang kita buat minggu lepas sudah mula pudar.',
  'adviser.home.middle': 'Teruskan. Perkara yang sama di tempat yang sama makin kurang kesannya, jadi pelbagaikan: ceramah, turun padang, jentera, sedikit dalam talian. Jangan biar mereka jadikan ini soal negara; kekalkan ia soal di sini.',
  'quick.home': 'Atau pimpin parti Sabah atau Sarawak di tanahnya sendiri:',
  'adviser.welcomeAny': 'Bos, selamat datang. Kerusi ini kosong dan kita ada tiga minggu untuk merampasnya. Saya akan tunjukkan caranya.',
  'adviser.welcomeAnyHeld': 'Bos, selamat datang. Kerusi ini kosong dan kita ada tiga minggu untuk mempertahankannya. Kali lalu kita menang. Saya akan tunjukkan caranya.',
  'nation.title': 'Keadaan negara',
  'nation.health': 'Kesihatan',
  'nation.education': 'Pendidikan',
  'nation.standing': 'Kedudukan antarabangsa',
  'nation.weak': 'Lemah',
  'nation.fair': 'Sederhana',
  'nation.strong': 'Kukuh',
  'nation.note.gov': 'Ini tanggungjawab anda. Ia bergerak perlahan mengikut garis belanjawan kesihatan dan pendidikan, menteri, serta betapa mantap dan dipercayainya kerajaan, dan melonjak bila sesuatu berlaku. Pengundi perasan.',
  'nation.note.opp': 'Kerajaan yang bertanggungjawab ke atas ini. Ia bergerak perlahan mengikut belanjawan, menteri dan kemantapannya, dan melonjak bila sesuatu berlaku. Pengundi perasan, dan anda juga boleh.',
  'menu.button': 'Menu',
