  'menu.new': 'Permainan baharu',
  'menu.main': 'Menu utama',
  'menu.note': 'Mula semula mengekalkan pertandingan, parti dan tetapan yang sama. Permainan disimpan sendiri semasa anda bermain, dan Sambung di menu utama membawanya kembali. Mula semula menggantikan simpanan automatik itu, jadi simpan ke slot dahulu jika mahu kekalkan permainan ini.',
