  'review.blocs.note': 'Bahagian undi parti anda dalam setiap kumpulan di seluruh negara, seperti yang dimodelkan permainan ini, berbanding pilihan raya lalu. Ia campuran arus kebangsaan dan apa yang anda lakukan.',
