  'title.intro': 'Pimpin sebuah parti ke hari mengundi. Mulakan dengan satu kerusi, rebut sebuah negeri, atau tawan kesemua 222 kerusi.',
  'title.contest': 'Pertandingan',
  'title.startHere': 'Mula di sini',
  'quick.title': 'Mula pantas',
  'quick.body': 'Pilihan raya kecil tiga minggu, dengan {adviser} di sisi anda menerangkan setiap langkah. Tidak perlu sebarang tetapan.',
  'quick.party': 'Anda memimpin',
  'quick.start': 'Mulakan tutorial',
  'quick.customise': 'Ubah suai sendiri',
  'quick.later': 'Pertandingan lain, pemimpin berlatar belakang, parti sendiri dan tahap kesukaran ada di bawah Ubah suai.',
  'quick.back': 'Kembali ke mula pantas',
  'title.fiction': 'Satira. Semua parti dan tokoh di dalamnya adalah rekaan.',
  'credits.title': 'Perihal dan penghargaan',
  'credits.fiction': 'Kempen 222 ialah karya fiksyen dan satira. Setiap parti, pemimpin, menteri, calon, akhbar, peristiwa dan berita di dalamnya adalah rekaan. Sebarang persamaan dengan orang atau pertubuhan sebenar ialah sifat parodi ini, bukan pernyataan fakta tentang sesiapa. Ia tidak bersekutu dengan atau disokong oleh mana-mana parti politik, badan kerajaan, Istana, atau institusi yang disebut.',
  'credits.data': 'Peta, senarai kerusi, bilangan pengundi dan keputusan lalu ialah data awam sebenar, diubah untuk permainan seperti yang diterangkan di bawah.',
  'credits.dosm': 'Jabatan Perangkaan Malaysia (DOSM): sempadan kerusi dan negeri serta angka banci 2020, di bawah Lesen Data Terbukanya. Ini bukan produk rasmi DOSM dan DOSM tidak menyokongnya.',
  'credits.tindak': 'Tindak Malaysia: set data keputusan PRU15, di bawah',
  'credits.link.dosm': 'data terbuka DOSM',
  'credits.link.tindak': 'set data PRU15',
  'credits.tindak2': 'Tindak Malaysia: keputusan pilihan raya negeri Melaka dan Sarawak (2021), lima negeri pada Ogos 2023, Sabah (2025), serta Johor dan Negeri Sembilan (2026). Sumbernya: Suruhanjaya Pilihan Raya Malaysia, Tindak Malaysia, Jabatan Peguam Negara, Bernama, RTM, Berita Harian, Sinar Harian, Harian Metro, Kosmo, Utusan Malaysia, Malaysiakini, Free Malaysia Today, Malaysia Gazette, Harakahdaily, The Edge, New Straits Times, The Star, Utusan TV, Astro Awani, Akhbar Rakyat, Sinar Project, serta laman dan penerbitan parti-parti sendiri (disenaraikan penuh dalam nota data projek). Di bawah',
  'credits.link.tindak2': 'keputusan pilihan raya terdahulu',
  'credits.changes': 'Perubahan yang dibuat: gabungan sebenar diganti dengan parti rekaan; parti kecil dan calon bebas digabungkan; sempadan dipermudah; dan campuran kelompok pengundi setiap kerusi ialah anggaran daripada angka banci, bukan statistik yang diterbitkan. Di enam negeri yang mengundi pada 2023, dan di Sabah, dua parti sekutu saling memberi laluan di setiap kerusi; undi setiap satu jika semua bertanding juga satu anggaran. Di Sabah, parti-parti yang kemudiannya memerintah bersama bertanding di bawah dua panji, dan dikira sebagai satu parti.',
  'error.title': 'Ada sesuatu yang tidak kena',
  'error.body': 'Permainan menemui ralat yang tidak dijangka. Ia disimpan secara automatik pada peranti ini, jadi memuat semula patut membawa anda kembali. Untuk lebih selamat, eksport permainan semasa ke fail dahulu.',
