  'title.stateMode.career.desc': 'Lima tahun antara pilihan raya dewan: memerintah negeri atau menjadi pembangkang, harungi apa yang berlaku, kemudian bertarung dalam pilihan raya seterusnya. Dan ulang lagi.',
