  'adviser.name': 'Kak Ros',
  'adviser.role': 'pengurus kempen',
  'adviser.next': 'Seterusnya',
  'adviser.skip': 'Langkau tutorial',
  'adviser.danger.unity': 'Perpaduan jatuh ke {n}. Di bawah paras ini, orang mula keluar. Tab Rundingan ialah tempat memulihkannya.',
  'adviser.danger.credibility': 'Kebolehpercayaan jatuh ke {n}. Pengundi tidak lagi percaya parti yang kerap berubah fikiran. Tetapkan pendirian anda seketika.',
  'adviser.danger.stability': 'Kestabilan jatuh ke {n}. Kerajaan serapuh ini boleh tumbang dengan satu undi. Lihat tab Arahan.',
  'adviser.danger.trust': 'Kepercayaan rakyat jatuh ke {n}. Pilihan raya akan datang akan sukar melainkan ia pulih. Lihat tab Arahan.',
  'adviser.danger.go': 'Bawa saya ke sana',
  'adviser.danger.later': 'Bukan minggu ini',
  'adviser.show': 'Tunjukkan',
  'adviser.welcome': 'Bos, selamat datang. Ahli Parlimen sudah meletak jawatan dan kita ada tiga minggu untuk merampas kerusi ini. Kali lalu pertandingan tiga penjuru yang sengit dan kita tewas. Saya akan tunjukkan caranya.',
  'adviser.welcomeHeld': 'Bos, selamat datang. Ahli Parlimen sudah meletak jawatan dan kita ada tiga minggu untuk mempertahankan kerusi ini. Kali lalu kita menang dalam pertandingan tiga penjuru yang sengit. Saya akan tunjukkan caranya.',
  'adviser.seat': 'Mula-mula, tengok keadaan di lapangan. Klik kerusi pada peta untuk membuka failnya.',
  'adviser.ceramah': 'Bagus. Sekarang cuba ceramah: dalam tab Tindakan, adakan satu. Ia memakan sehari dan sedikit wang. Kesannya bergantung pada kerusi, dan kerusi luar bandar paling terpengaruh dengan ceramah.',
  'adviser.poll': 'Adakah ia membantu? Kita tidak tahu selagi tidak bertanya. Buka tab Tinjauan dan tempah tinjauan kerusi. Ringkas itu murah dan kasar; Penuh lebih mahal dan lebih tepat.',
  'adviser.canvass': 'Setiap tinjauan ada ralat, jadi jangan cepat bersorak atas perubahan kecil. Sekarang gerakkan jentera: jalankan kempen rumah ke rumah dari tab Tindakan.',
  'adviser.funds': 'Semua ini memerlukan wang, dan kita tidak banyak wang. Kutip sedikit: majlis makan malam dana atau rayuan dalam talian.',
  'adviser.endWeek': 'Seminggu hanya ada tujuh hari. Apabila selesai, tekan Tamat minggu. Hari yang tidak digunakan akan hangus.',
  'adviser.rivals': 'Pihak lawan tidak duduk diam. Tab Berita menunjukkan apa yang mereka buat secara terbuka. Dan ingat: usaha kita minggu lalu sudah mula pudar, jadi minggu terakhir paling penting.',
  'adviser.middle': 'Teruskan. Perkara yang sama di tempat yang sama semakin kurang kesannya, jadi pelbagaikan: ceramah, turun padang, jentera, sedikit media sosial. Tamatkan minggu apabila selesai.',
  'adviser.gotv': 'Minggu terakhir. Memujuk hampir selesai; sekarang kita bawa orang kita ke pusat mengundi. Jalankan Gerak keluar mengundi dari tab Tindakan.',
  'adviser.pollingDay': 'Itu sahaja yang kita mampu. Habiskan hari yang berbaki, kemudian tekan Ke hari mengundi. Apa pun keputusannya, anda telah berkempen dengan betul.',

  'tab.chiefs': 'Ketua',
  'chiefs.title.general': 'Pengerusi negeri',
  'chiefs.title.state': 'Ketua bahagian',
  'chiefs.count': '{n} daripada {total} dilantik',
  'chiefs.intro.general': 'Lantik pengerusi negeri dan beliau menggerakkan kempen akar umbi di negeri itu bagi pihak anda: ceramah dan turun padang di kerusi paling sengit, kempen rumah ke rumah, papan iklan, cawangan baharu dan gerak keluar mengundi. Ia tidak mengambil hari anda. Mereka membelanjakan wang parti, dan acara mereka menarik separuh daripada hadirin acara anda.',
  'chiefs.intro.state': 'Lantik ketua bahagian dan beliau menggerakkan kempen akar umbi di kawasan itu bagi pihak anda: ceramah dan turun padang di kerusi paling sengit, kempen rumah ke rumah, papan iklan, cawangan baharu dan gerak keluar mengundi. Ia tidak mengambil hari anda. Mereka membelanjakan wang parti, dan acara mereka menarik separuh daripada hadirin acara anda.',
  'chiefs.when': 'Ketua bertindak apabila anda menamatkan minggu. Mereka berjimat pada awal kempen, berbelanja paling banyak pada minggu-minggu terakhir, dan tidak mengulangi apa yang anda sendiri sudah lakukan.',
  'chiefs.people': 'Ketua itu seorang manusia. Yang berkebolehan menarik lebih ramai orang. Setiap seorang setia selagi anda muncul di kawasannya dan menjauh apabila anda tidak datang; yang dibiarkan menjauh mungkin menyeberang kepada pesaing dan membawa cawangan bersamanya.',
  'chiefs.skill': 'Kebolehan',
  'chiefs.mood.loyal': 'Setia',
