  'news.chief.defected': '{name}, ketua anda di {state}, menyeberang kepada {party} dan membawa cawangan bersamanya. Seorang timbalan menunggu untuk dilantik.',
  'news.chief.exposed': 'Cerita lama tentang {name}, ketua anda di {state}, terpampang di setiap muka depan. Dia berundur, dan seorang timbalan menunggu untuk dilantik.',
  'chiefs.all': 'Tetapkan semua',
  'chiefs.floor': 'Ketua mesti meninggalkan sekurang-kurangnya',
