  'deals.intro': 'Pilihan raya dimenangi dengan kira-kira, bukan undi semata-mata. Duduk semeja dengan pemimpin lain, persetujui siapa memberi laluan di mana, dan cari kawan untuk pagi selepas mengundi.',
  'deals.nomination': 'Hari penamaan calon jatuh pada hujung minggu {n}. Sebelum itu anda boleh membuat pakatan dan memujuk wakil rakyat melompat; selepas itu, calon tidak boleh diubah.',
