  'pact.intro': 'Bagi setiap kerusi yang ditandingi kedua-dua pihak, pilih siapa yang bertanding. Apabila satu pihak memberi laluan, kebanyakan pengundinya beralih kepada pihak satu lagi; sebahagian tidak keluar mengundi dan sebahagian ke parti lain.',
