  'scene.poach.body': 'Penyandang anda di {seat} dilihat makan tengah hari yang panjang bersama {party}. Beliau sedang berfikir untuk melompat, dan membawa undi peribadinya bersama.',
  'scene.poach.pay': 'Cari {rm} untuk “kerja kawasan” beliau',
  'scene.poach.appeal': 'Rayu kesetiaan beliau ({pct} peluang)',
