  'scene.palace.title': 'Menghadap di Istana',
  'scene.summons.body.general': 'Tiada parti mendapat majoriti. Istana meminta setiap pemimpin yang yakin mendapat kepercayaan Dewan supaya membuktikannya: {n} ahli, dalam tempoh {days} hari.',
  'scene.summons.body.state': 'Tiada parti mendapat majoriti. Istana meminta setiap pemimpin yang yakin mendapat kepercayaan Dewan Undangan Negeri supaya membuktikannya: {n} ahli, dalam tempoh {days} hari.',
  'scene.palace.ack': 'Menjunjung kasih, Tuanku',
  'scene.unity.body': 'Belum ada pemimpin yang menunjukkan majoriti. Demi kestabilan, Istana menasihatkan para pemimpin supaya mempertimbangkan kerajaan perpaduan, dan mendahulukan negara daripada perbezaan mereka.',
  'scene.unity.explore': 'Patik akan menelitinya, Tuanku',
  'scene.unity.decline': 'Ampun Tuanku, patik yakin dapat menunjukkan majoriti',
  'news.meet': 'Teh tarik bersama {leader}. Tiada apa yang dipersetujui, dan itu sudah dikira kemajuan.',
  'news.understanding': '{leader} berbisik kepada anda: sokongan mereka selepas hari mengundi, jika semuanya berjalan lancar.',
  'news.pact.mine': 'Anda dan {party} menandatangani pakatan pilihan raya meliputi {n} kerusi.',
  'news.pact.signed': '{a} dan {b} menandatangani pakatan pilihan raya meliputi {n} kerusi.',
