  'scene.agenda.from': 'Negeri',
  'news.term.limited': 'Had penggal yang anda lulus terpakai kepada anda sendiri: selepas {n} parlimen mengetuai kerajaan, parti memerintah dan anda tidak. Pengganti dari parti anda menjadi perdana menteri, dan anda memimpin parti dari luar jawatan itu.',
  'news.grassroots': 'Bertahun-tahun ahli dan cawangan membuahkan hasil: organisasi parti bernilai kira-kira {pts} mata undi, di mana-mana parti bertanding.',
  'party.grassroots': 'Pada pilihan raya akan datang, ahli dan cawangan anda bernilai kira-kira {pts} mata undi, di mana-mana anda bertanding. Ia perlukan kedua-duanya: ahli jauh lebih ramai daripada biasa, dan cawangan yang kuat.',
  'party.factions': 'Faksi dan sayap',
  'party.factions.desc': 'Parti bersidang setiap {n} tahun untuk memilih pemimpin, dan pemimpin yang tidak disokong ahli boleh dicabar: dan kalah. Sokongan sekarang {pct}; peluang dicabar pada perhimpunan akan datang {chance}.',
  'party.faction.line': '{size}% daripada ahli · perasaan terhadap anda {mood}',
