  'faction.loyalists': 'Penyokong setia',
  'faction.loyalists.desc': 'Terhutang segala-galanya kepada pemimpin. Bersama sesiapa yang menyatukan parti dan memegang jawatan.',
  'faction.reformers': 'Golongan pembaharu',
  'faction.reformers.desc': 'Mahu parti menjadi seperti yang dikatakannya. Memerhati kredibiliti anda, kepercayaan rakyat dan pendirian anda tentang pembaharuan.',
  'faction.veterans': 'Golongan veteran',
  'faction.veterans.desc': 'Ingat bagaimana parti dahulu menang. Suka wang, parti yang mereka kenali dan pemimpin yang tidak bercakap tentang pembaharuan.',
