  'partyPoll.title': 'Parti bersidang',
  'partyPoll.body': 'Tiga tahun berlalu, parti bersidang memilih pemimpin, dan {faction} telah mengemukakan pencabar. Ahli secara keseluruhan menilai anda {pct} daripada 100. Kalah, dan anda keluar.',
