  'redraw.title': 'Sempadan akan dilukis semula',
  'redraw.body': 'Suruhanjaya Pilihan Raya akan melukis semula kawasan sebelum parlimen seterusnya. Kerajaan sentiasa ada pengaruhnya, walau apa yang dikatakan di depan umum. Anda boleh menyerahkannya kepada suruhanjaya, atau meminta peta yang menguntungkan parti: pengundi kerusi paling selamat anda dipindahkan ke kerusi paling tipis yang dipegang pihak lain.',
