  'news.palace.refused': 'Istana menolak permohonan anda untuk membubarkan Parlimen, dan meminta kerajaan menunjukkan bahawa ia masih menguasai Dewan. Anda boleh memohon semula dalam {n} minggu, dan penolakan itu menggugat kerajaan.',
  'form.invited': 'Istana mula-mula menjemput {party}, yang mempunyai sokongan paling banyak, untuk menunjukkan ia menguasai majoriti.',
  'measures.title': 'Apa yang dibiayai belanjawan',
  'measures.desc': 'Sehingga {n} perkara khusus dalam barisan di atas. Setiap satu kos sedikit lebih daripada mengekalkan barisan, dan disedari oleh mereka yang dituju.',
