  'committee.title': 'Jawatankuasa pilihan',
  'committee.desc': 'Pembangkang boleh memanggil kerajaan ke jawatankuasa Dewan dan membelanjakan apa yang telah digali parti. Ia memerlukan dossier sekurang-kurangnya {dossier}, {rm}, dan jawatankuasa bersidang sekali setiap {n} minggu. Jawatankuasa yang tidak menemui apa-apa ialah hadiah kepada pihak lawan.',
