  'expel.title': 'Singkirkan rakan',
  'expel.desc': 'Ketua kerajaan boleh menyingkirkan rakan daripada kabinet. Ia menjadi musuh, rakan lain gelisah, dan kerajaan kurang kukuh. Tidak boleh jika kerajaan kehilangan majoriti selepas itu.',
