  'supply.desc': 'Parti yang tidak mahu duduk dalam kabinet masih boleh mengekalkan kerajaan selama setahun, sebagai balasan wang atau apa yang paling diingininya. Ia mengundi bersama kerajaan dalam undi keyakinan dan belanjawan; apabila setahun tamat, perjanjian luput.',
