  'party.chest': 'Dana perang',
  'party.chest.desc': 'Wang yang diketepikan tidak boleh disentuh antara pilihan raya, dan keluar apabila kempen bermula dengan tambahan {bonus}% daripada penderma. Mengambilnya semula lebih awal kos {penalty}%.',
  'party.chest.held': 'Diketepikan: {rm}',
