  'party.fatigue': 'Ini parlimen ke-{n} berturut-turut dalam kerajaan. Pengundi sudah jemu dengan parti: ia kos kira-kira {pts} mata undi, di mana-mana.',
  'party.foreign': 'Wang dari luar negara',
  'party.foreign.desc': 'Seorang penderma luar negara akan memberi {rm} sekali gus, sekali setiap parlimen, untuk satu budi: pendirian parti beralih satu langkah mengikut kehendaknya. Kalau terbongkar, ia skandal terbesar.',
