  'party.discipline.confirm': 'Pasti?',
  'party.rebrand': 'Nama baharu',
  'party.rebrand.desc': 'Parti boleh mengambil nama, bendera dan warna baharu, sekali setiap parlimen. Kosnya {rm} dan {cred} kredibiliti; sebahagian pengundi setia lama dan beberapa ahli pergi, dan anak muda, bandar dan pinggir bandar melihat sekali lagi.',
