  'news.rebrand': 'Parti muncul dengan nama, bendera dan warna baharu. Pengundi lama menggeleng; anak muda, bandar dan pinggir bandar melihat sekali lagi.',
  'news.discipline.suspend': 'Kepimpinan menggantung cawangan parti di {state}. Ia menjadi sunyi, dan seluruh parti faham maksudnya.',
  'news.discipline.dissolve': 'Kepimpinan membubarkan cawangan parti di {state} dan menghantar pegawainya pulang. Ia mengambil bertahun-tahun untuk dibina semula, dan tiada orang lain yang akan melanggar barisan untuk seketika.',
