  'orders.source.crowd.desc': 'Banyak sumbangan kecil kepada parti pembangkang yang dihormati. Lebih bermakna untuk parti yang kosong dompetnya. Tiada bila memerintah.',
  'party.pad': 'Ahli atas kertas',
  'party.pad.desc': 'Senarai ahli boleh digelembungkan {pct}% dengan nama yang bukan ahli: lebih yuran dan gambaran kekuatan, tetapi bila terbongkar, parti membayarnya. Sekali setiap parlimen.',
