  'slate.leader': 'Anda bertanding sendiri di {seat}. Kalah di situ, dan anda hilang kerusi dalam Dewan, apa pun yang parti lakukan.',
  'news.candidate.scandals': 'Masa lalu {n} calon pilihan parti sendiri terbongkar: {seats}.',
  'news.leader.stands': 'Pemimpin meletakkan dirinya sebagai calon di {seat}.',
  'news.leader.lost': 'Pemimpin kalah di kerusi tempat beliau bertanding, {seat}. Parti tergugat; beliau memimpinnya dari luar Dewan.',
  'news.leader.lost.pm': 'Parti telah menang, dan pemimpin kalah di kerusi tempat beliau bertanding, {seat}. Beliau tidak boleh menjadi perdana menteri tanpa kerusi: pengganti dari partinya mengambil jawatan itu, dan pemimpin menunggu di luar Dewan.',
  'party.merge': 'Menyerap sekutu',
  'party.merge.desc': 'Sekutu kecil boleh diserap ke dalam parti: kerusi, ahli dan pengundinya menjadi milik anda, dan pada pilihan raya akan datang ia tidak bertanding. Kosnya perpaduan dan sedikit kredibiliti, dan parti mengambil satu langkah ke arah apa yang dipercayai sekutu itu. Terbuka kepada parti yang pemimpinnya sekurang-kurangnya {warm} mesra terhadap anda dan tidak melebihi {n}% kerusi anda.',
  'party.merge.done': 'Sudah diserap: {parties}.',
