  'challenge.realStates': 'Bertanding sendiri dalam pilihan raya negeri',
  'challenge.realStates.desc': 'Bila tiba pusingan pilihan raya negeri, anda boleh bertanding sendiri di mana-mana negerinya sebagai kempen tersendiri, dibiayai daripada dana parti setakat yang ada. Selebihnya diputuskan oleh permainan, seperti biasa.',
  'fight.title': 'Bertanding sendiri',
  'fight.desc': 'Anda boleh bertanding sendiri di mana-mana negeri ini: enam minggu di negeri itu, seperti pilihan raya negeri, dibiayai dengan dana pertandingan itu. Yang tidak dibelanjakan dikembalikan kepada parti. Negeri lain diserahkan kepada permainan, dengan usaha yang anda pilih di bawah.',
  'fight.holds': 'dipegang {party}',
  'fight.cost': 'dana {rm}',
  'fight.short': 'wang tidak cukup',
  'fight.cant': 'parti anda tidak bertanding di sini',
  'fight.loading': 'memuat keputusannya',
  'fight.total': 'Bertanding di {n}: anda melabur {rm} daripada {funds}. Memilih tahap usaha untuk yang lain, di bawah, memulakannya.',
  'fight.banner': 'Pilihan raya negeri di {state}, sebagai sebahagian daripada kerjaya anda.',
  'fight.banner.more': 'Pilihan raya negeri di {state}, sebagai sebahagian daripada kerjaya anda. {n} lagi dalam pusingan ini selepasnya.',
  'fight.next': 'Negeri seterusnya: {state}',
  'fight.back': 'Kembali ke kerjaya anda',
  'news.states.fought': '{state}: parti anda bertanding sendiri dan menang {seats} kerusi. {party} membentuk kerajaan.',
  'house.cabinet.note': 'Menteri Kewangan yang cekap mengurangkan defisit; menteri yang cekap membawa rang undang-undang ke undian lebih cepat. Lantikan baharu satu perjudian.',
  'house.skill': 'kebolehan {n} daripada 5',
  'house.reshuffle': 'Ganti',
  'house.reshuffle.own': 'Perpaduan berkurang 2. Ganti?',
  'house.reshuffle.theirs': 'Mengambil jawatan daripada rakan. Ganti?',
  'house.promises': 'Janji anda',
  'house.promises.desc': 'Apa yang anda janjikan pada pilihan raya lalu. Setiap satu memerlukan rang undang-undang yang diluluskan Dewan; sehingga {n} boleh disediakan serentak. Janji yang tidak pernah dibawa ke undian akan dipersoalkan pada pilihan raya akan datang.',
  'house.promises.none': 'Anda tidak membuat sebarang janji pada pilihan raya lalu.',
  'house.whip': 'Sokong {yes} · bantah {no} · atas pagar {wavering}',
