  'house.bill.failed': 'Ditolak atau ditarik balik.',
  'house.bill.inHouse': 'Di hadapan Dewan: undian dalam {n} minggu',
  'house.table': 'Bentang ({n} minggu)',
  'house.owed': 'Hutang janji kepada rakan',
  'house.owed.none': 'Anda tidak berhutang apa-apa yang khusus kepada rakan gabungan.',
  'house.owed.done': 'ditunaikan',
  'house.owed.due': 'perlu dalam {n} minggu',
  'house.owed.later': 'perlu dalam {n} minggu',
  'house.owed.bill': 'Memerlukan rang undang-undang di Dewan.',
  'house.owed.shady': 'Dilakukan terang-terangan, ia menjejaskan kredibiliti.',
  'house.owed.free': 'Cukup dengan satu tandatangan.',
  'house.deliver': 'Tunaikan',
  'house.levers': 'Institusi',
  'house.levers.desc': 'Institusi ini sepatutnya bebas. Kerajaan boleh menekan setiap satu sekali setahun, dan membayarnya dengan kepercayaan rakyat.',
  'lever.agency': 'Agensi antirasuah',
  'lever.agency.desc': 'Buka kertas siasatan ke atas parti pembangkang utama. Biasanya menjejaskan mereka; tiga daripada sepuluh kali ia melahirkan wira.',
  'lever.police': 'Polis',
  'lever.police.desc': 'Tolak permit himpunan pembangkang selama semusim. Mereka hilang daripada berita, dan orang muda serta golongan liberal marah.',
  'lever.broadcaster': 'Penyiar kerajaan',
  'lever.broadcaster.desc': 'Semusim liputan yang memuji. Menaikkan profil anda, menjejaskan kredibiliti.',
  'house.lever.pull': 'Beri tekanan',
  'house.lever.confirm': 'Menjejaskan kepercayaan rakyat. Teruskan?',
  'house.parliament': 'Kepercayaan',
  'house.confidence': 'Kerajaan pimpinan {party} boleh mengharapkan {n} ahli dalam undi percaya; ia memerlukan {need}.',
  'house.motion': 'Usul undi tidak percaya',
  'house.motion.desc': 'Jika diluluskan, kerajaan tumbang dan Istana bertanya siapa boleh membentuk kerajaan baharu. Jika gagal, anda kelihatan bodoh dan mereka kelihatan lebih kuat. Sekali setahun.',
  'house.motion.table': 'Bentang usul',
  'house.motion.confirm': 'Paksa undian?',
  'house.leave': 'Keluar daripada kerajaan',
  'house.leave.desc': 'Bawa ahli anda ke blok pembangkang. Jika kerajaan hilang majoriti, rundingan bermula.',
  'house.leave.go': 'Keluar',
  'house.leave.confirm': 'Betul mahu keluar?',
