  'scene.from.house': 'Di Dewan',
  'scene.later': 'Tinjau dahulu',
  'scene.waiting': 'Satu keputusan menanti di meja anda. Masa terhenti sehingga anda memutuskannya.',
  'scene.open': 'Buka',
  'scene.vote.title': 'Undian: {bill}',
  'scene.vote.body': 'Rang undang-undang anda sedia diundi. Ketua whip sudah mengira; yang atas pagar boleh ke mana-mana.',
  'scene.vote.o0': 'Bawa ke undian',
